#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Use a markdown library to convert markdown to HTML
    // This is a simple example and will work for basic markdown syntax
    // For a more robust solution, consider using a markdown library like gdown
    // or a specialized library like Marked++.

    std::string html;
    std::stringstream ss(markdown);
    std::string line;
    while (std::getline(ss, line)) {
        html += line + "\n";
    }
    return html;
}

int main() {
    // Example usage
    std::string markdown = "# Header\n\nThis is a test paragraph with **bold** text and _italic_ text.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

